--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,12 +6,56 @@ export interface Record {
   warns: readonly string[];
 }

+const extractKeywords = (text: string): Set<string> => {
+  return new Set(
+    text
+      .toLowerCase()
+      .split(/\W+/)
+      .filter((w) => w.length > 2 && !["and", "the", "for", "not", "one"].includes(w))
+  );
+};
+
+const calculateSimilarity = (a: string, b: string): number => {
+  const keywordsA = extractKeywords(a);
+  const keywordsB = extractKeywords(b);
+  const intersection = [...keywordsA].filter((k) => keywordsB.has(k)).length;
+  const union = new Set([...keywordsA, ...keywordsB]).size;
+  return union === 0 ? 0 : intersection / union;
+};
+
+const deduplicateEntries = (entries: readonly string[]): string[] => {
+  if (entries.length === 0) return [];
+
+  const groups: { representative: string; similar: Set<number> }[] = [];
+
+  for (let i = 0; i < entries.length; i++) {
+    let foundGroup = false;
+
+    for (const group of groups) {
+      if (calculateSimilarity(entries[i], group.representative) > 0.4) {
+        group.similar.add(i);
+        foundGroup = true;
+        break;
+      }
+    }
+
+    if (!foundGroup) {
+      groups.push({ representative: entries[i], similar: new Set([i]) });
+    }
+  }
+
+  return groups.map((g) => g.representative);
+};
+
 export const project = (records: readonly Record[]): string => {
   const lines: string[] = [];
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    for (const entry of deduplicateEntries(record.ruledOut))
+      lines.push(`- ruled out: ${entry}`);
+    for (const limit of deduplicateEntries(record.limits))
+      lines.push(`- limit: ${limit}`);
+    for (const warn of deduplicateEntries(record.warns))
+      lines.push(`- warn: ${warn}`);
   }
   return lines.join("\n");
 };
